import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
import 'dart:convert'; // For jsonDecode

class NetworkingPage extends StatefulWidget {
  @override
  _NetworkingPageState createState() => _NetworkingPageState();
}

class _NetworkingPageState extends State<NetworkingPage> {
  String _data = "Press the button to fetch data";
  bool _isLoading = false;

  Future<void> _fetchData() async {
    setState(() => _isLoading = true);

    try {
      // Use a free public API for demonstration
      final response = await http.get(Uri.parse('https://jsonplaceholder.typicode.com/posts/1'));

      if (response.statusCode == 200) {
        // If the server returns a 200 OK response, parse the JSON.
        final json = jsonDecode(response.body);
        setState(() {
          _data = "Title: ${json['title']}";
        });
      } else {
        // If the server did not return a 200 OK response,
        // throw an exception.
        setState(() {
          _data = 'Failed to load data. Status code: ${response.statusCode}';
        });
      }
    } catch (e) {
      setState(() {
        _data = 'An error occurred: $e';
      });
    } finally {
      setState(() => _isLoading = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text("Networking Demo")),
      body: Center(
        child: Padding(
          padding: const EdgeInsets.all(16.0),
          child: _isLoading
              ? CircularProgressIndicator()
              : Column(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                    Text(_data, textAlign: TextAlign.center),
                    SizedBox(height: 20),
                    ElevatedButton(
                      onPressed: _fetchData,
                      child: Text("Fetch Data"),
                    ),
                  ],
                ),
        ),
      ),
    );
  }
}

