class OfflineAwareWidget extends StatelessWidget {
  final Widget onlineChild;
  final Widget offlineChild;

  const OfflineAwareWidget({
    Key? key,
    required this.onlineChild,
    required this.offlineChild,
  }) : super(key: key);

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<List<ConnectivityResult>>(
      stream: Connectivity().onConnectivityChanged,
      initialData: const [ConnectivityResult.mobile], // Assume online initially
      builder: (context, snapshot) {
        if (snapshot.hasData && snapshot.data!.first != ConnectivityResult.none) {
          // If connected, show the online child
          return onlineChild;
        } else {
          // If offline, show the offline child
          return offlineChild;
        }
      },
    );
  }
}

